import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';

const Navbar = ({ onNavigate }) => { // ✅ Используем пропс onNavigate вместо useNavigate
  const [searchTerm, setSearchTerm] = useState('');
  const { user, cart } = useAuth();

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      onNavigate('catalog'); // ✅ Используем onNavigate
    }
  };

  const cartItemsCount = cart.reduce((total, item) => total + (item.quantity || 1), 0);

  return (
    <nav className="bg-white shadow-lg border-b">
      <div className="max-w-7xl mx-auto px-4">
        <div className="flex justify-between items-center h-16">
          {/* Logo */}
          <button 
            onClick={() => onNavigate('home')} // ✅ Используем onNavigate
            className="flex items-center"
          >
            <span className="ml-2 text-xl font-serif font-bold">LUNA AUREA</span>
          </button>

          {/* Navigation Links */}
          <div className="hidden md:flex space-x-8">
            <button 
              onClick={() => onNavigate('catalog')} // ✅ Используем onNavigate
              className="text-gray-700 hover:text-gold-600 font-medium"
            >
              КАТАЛОГ
            </button>
            <button 
              onClick={() => onNavigate('catalog')}
              className="text-gray-700 hover:text-gold-600 font-medium"
            >
              КОЛЛЕКЦИИ
            </button>
          </div>

          {/* Icons */}
          <div className="flex items-center space-x-4">
            {/* Search */}
            <form onSubmit={handleSearch} className="relative">
              <input
                type="text"
                placeholder="Поиск украшений..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-4 pr-10 py-2 border border-gray-300 rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-gold-500 focus:border-transparent w-64"
              />
              <button 
                type="submit" 
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gold-600"
              >
                🔍
              </button>
            </form>

            {/* Profile */}
            <button 
              onClick={() => onNavigate(user ? "profile" : "auth")} // ✅ Используем onNavigate
              className="p-2 hover:bg-gray-100 rounded-full transition-colors"
              title="Профиль"
            >
              👤
            </button>

            {/* Cart */}
            <button 
              onClick={() => onNavigate("profile")} // ✅ Используем onNavigate
              className="p-2 hover:bg-gray-100 rounded-full relative transition-colors"
              title="Корзина"
            >
              🛒
              {cartItemsCount > 0 && (
                <span className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-5 h-5 text-xs flex items-center justify-center">
                  {cartItemsCount}
                </span>
              )}
            </button>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
